# index of bit z of lane (x, y)
@inline
def ix(x, y, z):
    return 64 * (x + 5 * y) + z


@inline
def xor2(a, b):
    return a + b - 2 * a * b


def keccak_round(a, out, rcb):
    c = Array(320)
    for x in unroll(0, 5):
        for z in unroll(0, 64):
            t0 = xor2(a[64 * x + z], a[64 * (x + 5) + z])
            t1 = xor2(t0, a[64 * (x + 10) + z])
            t2 = xor2(t1, a[64 * (x + 15) + z])
            c[64 * x + z] = xor2(t2, a[64 * (x + 20) + z])
    d = Array(320)
    for x in unroll(0, 5):
        for z in unroll(0, 64):
            d[64 * x + z] = xor2(c[64 * ((x + 4) % 5) + z], c[64 * ((x + 1) % 5) + (z + 63) % 64])
    b = Array(1600)
    for x in unroll(0, 5):
        for y in unroll(0, 5):
            for z in unroll(0, 64):
                # B[y, 2x+3y] = rot(A'[x, y], RHO[x][y])
                b[64 * (y + 5 * ((2 * x + 3 * y) % 5)) + (z + RHO[x][y]) % 64] = xor2(a[64 * (x + 5 * y) + z], d[64 * x + z])
    for x in unroll(0, 5):
        for y in unroll(0, 5):
            for z in unroll(0, 64):
                b0 = b[64 * (x + 5 * y) + z]
                b1 = b[64 * ((x + 1) % 5 + 5 * y) + z]
                b2 = b[64 * ((x + 2) % 5 + 5 * y) + z]
                v = xor2(b0, (1 - b1) * b2)
                if x == 0:
                    if y == 0:
                        out[64 * (x + 5 * y) + z] = xor2(v, rcb[z])
                    else:
                        out[64 * (x + 5 * y) + z] = v
                else:
                    out[64 * (x + 5 * y) + z] = v
    return


def main():
    states = Array(25 * 1600)
    for i in unroll(0, 1600):
        states[i] = (i * 7 + div_floor(i, 3)) % 2
    rcs = Array(24 * 64)
    for r in unroll(0, 24):
        for z in unroll(0, 64):
            rcs[64 * r + z] = RC_BITS[r][z]
    for r in range(0, 24):
        keccak_round(states + r * 1600, states + (r + 1) * 1600, rcs + r * 64)
    return
